const express = require('express');
const app = express();

function versionedRoute(version) {
  return (req, res) => {
    const apiVersion = req.get('API-Version') || '1';
    if (apiVersion === '2') {
      return res.json({
        id: req.params.id,
        username: req.user.username,
        email: req.user.email,
        displayName: req.user.displayName,
        avatarUrl: req.user.avatarUrl
      });
    }
    // Default to v1
    return res.json({
      id: req.params.id,
      username: req.user.username,
      email: req.user.email
    });
  };
}

app.get('/users/:id', versionedRoute());
app.listen(3000);
